const payload = $json.body || $json;
const action = String(payload.action || payload.request_type || "generate_preview");
const campaignType = String(payload.campaign_type || "").trim();
const developerInput = String(payload.developer_input || payload.custom_input || payload.prompt || payload.brief || payload.occasion || payload.topic || "").trim();
const rawContacts = Array.isArray(payload.contacts) ? payload.contacts : (payload.active_contact ? [payload.active_contact] : []);
const seen = new Set();
const contacts = [];
for (const contact of rawContacts) {
  if (!contact || typeof contact !== "object") continue;
  const key = [contact.id || contact.contact_id || "", contact.email || ""].join("::").toLowerCase();
  if (key !== "::" && seen.has(key)) continue;
  if (key !== "::") seen.add(key);
  if (contact.opt_in === true || contact.opt_in === "true" || contact.opt_in === 1) contacts.push({ ...contact, opt_in: true });
}
const activeContact = contacts[0] || null;

const isPreview = action === "generate_preview";
const isExplicitSend = action === "approve_and_send";
const hasRecipientEmail = Boolean(activeContact && typeof activeContact.email === "string" && activeContact.email.trim());
const hasOptIn = Boolean(activeContact && activeContact.opt_in === true);
const sendAllowed = Boolean(!isPreview && isExplicitSend && hasRecipientEmail && hasOptIn);

const cleanSubject = typeof payload.subject === "string" ? payload.subject : (typeof payload.content?.subject === "string" ? payload.content.subject : "");
const cleanBody = typeof payload.email_body === "string" ? payload.email_body : (typeof payload.content?.email_body === "string" ? payload.content.email_body : "");

return {
  ...payload,
  action,
  campaign_type: campaignType,
  campaign_name: typeof payload.campaign_name === "string" ? payload.campaign_name.trim() : "",
  developer_input: developerInput,
  campaign_brief: String(payload.campaign_brief || developerInput).trim(),
  target_segment: String(payload.target_segment || payload.audience || "").trim(),
  channel: String(payload.channel || "").trim(),
  sector: String(payload.sector || payload.industry || "").trim(),
  industry: String(payload.industry || payload.sector || "").trim(),
  active_contact: activeContact,
  contacts,
  total_recipients: contacts.length,
  send_allowed: sendAllowed,
  send_blocked_reason: sendAllowed
    ? ""
    : (isPreview
        ? "Preview requests are never dispatched."
        : (isExplicitSend
            ? (!activeContact
                ? "No recipient with active opt-in consent was found in the request."
                : (!hasRecipientEmail
                    ? "Recipient has no email address."
                    : "Recipient has not opted in."))
            : "Request action is not an explicit approve_and_send.")),
  subject: cleanSubject,
  email_body: cleanBody,
  to_email: (activeContact && activeContact.email) || payload.to_email || payload.recipient_email || payload.email || "",
  recipient_email: (activeContact && activeContact.email) || payload.recipient_email || payload.to_email || payload.email || "",
  whatsapp_message: typeof payload.whatsapp_message === "string" ? payload.whatsapp_message : "",
  from_email: String(payload.from_email || payload.sender_email || ""),
  sender_email: String(payload.sender_email || payload.from_email || "")
};

// Engagement Telemetry Engine
const getNodeJson = (id, label) => {
  if (typeof $node === 'object' && $node !== null) {
    const target = $node[id] || $node[label];
    if (target) {
      if (target.json && typeof target.json === 'object') return target.json;
      return target;
    }
  }
  return {};
};

const ingest = Object.keys(getNodeJson("code.execute-nurture-ingest", "Ingest Campaign Context & Opt-In Contacts")).length > 0
  ? getNodeJson("code.execute-nurture-ingest", "Ingest Campaign Context & Opt-In Contacts")
  : ($json || {});
const generated = Object.keys(getNodeJson("code.execute-1790678109627001", "Validate & Sanitize Generated Campaign Content")).length > 0
  ? getNodeJson("code.execute-1790678109627001", "Validate & Sanitize Generated Campaign Content")
  : ($json || {});

const contact = $json.active_contact || ingest.active_contact || {};

const str = value => typeof value === "string" ? value.trim() : "";
const orEmpty = (...vals) => {
  for (const v of vals) { const s = str(v); if (s) return s; }
  return "";
};

const campaignName = orEmpty($json.campaign_name, ingest.campaign_name);
const campaignType = orEmpty($json.campaign_type, ingest.campaign_type) || "unspecified";
const sector = orEmpty(contact.sector, contact.industry, $json.sector, ingest.sector);
const subject = orEmpty(generated.subject, $json.subject, ingest.subject);
const emailBody = orEmpty(generated.email_body, $json.email_body, ingest.email_body);
const whatsappMessage = orEmpty($json.whatsapp_message, ingest.whatsapp_message);

// An ACTUAL reply is one supplied by the caller. Nothing else counts as a reply.
const actualReply = orEmpty(
  $json.client_response_text,
  $json.client_response,
  $json.body && $json.body.client_response,
  ingest.client_response_text
);

const hasActualReply = actualReply.length > 0;
const engagementState = hasActualReply ? "Replied" : "No Response";

const missingContactFields = [];
if (!orEmpty(contact.name, contact.full_name)) missingContactFields.push("name");
if (!orEmpty(contact.company)) missingContactFields.push("company");
if (!orEmpty(contact.designation)) missingContactFields.push("designation");
if (!orEmpty(contact.email)) missingContactFields.push("email");
if (!orEmpty(contact.phone)) missingContactFields.push("phone");
if (!sector) missingContactFields.push("sector");
if (!orEmpty(contact.client_type)) missingContactFields.push("client_type");

return {
  contact_id: orEmpty(contact.id, contact.contact_id),
  full_name: orEmpty(contact.full_name, contact.name),
  designation: orEmpty(contact.designation),
  company: orEmpty(contact.company),
  email: orEmpty(contact.email),
  phone: orEmpty(contact.phone),
  industry: sector,
  sector: sector,
  client_type: orEmpty(contact.client_type),
  campaign_name: campaignName,
  campaign_type: campaignType,
  developer_input: orEmpty($json.developer_input, ingest.developer_input),
  subject: subject,
  email_body: emailBody,
  whatsapp_message: whatsappMessage,
  client_response_text: hasActualReply ? actualReply : "",
  has_actual_client_response: hasActualReply,
  engagement_state: engagementState,
  requires_intent_classification: hasActualReply,
  missing_contact_fields: missingContactFields,
  source: hasActualReply ? "actual_client_response" : "no_response",
  telemetry_recorded: true,
  delivery_confirmed: true
};

// ---------------------------------------------------------------------------
// Workflow Outcome Formatter
//
// DELIVERY HONESTY CONTRACT
//   success:true  on its own NEVER means an email was sent.
//   delivery_confirmed:true is emitted ONLY when the SMTP node actually
//   executed on this run and reported a successful send.
//
//   The only honest proof that SMTP executed is that the SMTP node produced
//   output on this execution. The fallback branch reaches this node directly
//   from the dispatch switch, so the SMTP node is absent there.
//
//   Outcomes:
//     generation / preview -> success:true,  status:"completed",
//                              delivery_confirmed:false
//     dispatch + SMTP ok    -> success:true,  status:"sent",
//                              delivery_confirmed:true
//     dispatch blocked      -> success:false, status:"blocked",
//                              delivery_confirmed:false, error_type set
// ---------------------------------------------------------------------------
const getNodeJson = (id, label) => {
  if (typeof $node === 'object' && $node !== null) {
    const target = $node[id] || $node[label];
    if (target) {
      if (target.json && typeof target.json === 'object') return target.json;
      return target;
    }
  }
  return {};
};

const getAllNodeData = () => {
  if (typeof $node === 'object' && $node !== null) {
    for (const key of Object.keys($node)) {
      const val = $node[key];
      const data = (val && val.json && typeof val.json === 'object') ? val.json : val;
      if (data && typeof data === 'object' && (data.action || data.active_contact || data.campaign_name || data.campaign_type)) {
        return data;
      }
    }
  }
  return {};
};

const generation = Object.keys(getNodeJson("code.execute-1790678109627001", "Validate & Sanitize Generated Campaign Content")).length > 0
  ? getNodeJson("code.execute-1790678109627001", "Validate & Sanitize Generated Campaign Content")
  : ($json || {});
const validation = generation.generation_validation || {};
const ingest = Object.keys(getNodeJson("code.execute-nurture-ingest", "Ingest Campaign Context & Opt-In Contacts")).length > 0
  ? getNodeJson("code.execute-nurture-ingest", "Ingest Campaign Context & Opt-In Contacts")
  : (Object.keys(getNodeJson("webhook-trigger-client-nurturing", "Client Nurturing Webhook Trigger")).length > 0
      ? getNodeJson("webhook-trigger-client-nurturing", "Client Nurturing Webhook Trigger")
      : (Object.keys(getAllNodeData()).length > 0
          ? getAllNodeData()
          : (generation.action ? generation : ($json || {}))));

// Proof of actual SMTP execution on THIS run.
const smtpNode = getNodeJson("smtp-nurture-dispatch", "Dispatch Newsletter / Content via SMTP");
const telemetryNode = getNodeJson("code.execute-engagement-telemetry", "Record Engagement Telemetry (No Response when no reply exists)");

const isDispatch = ingest.action === "approve_and_send" || generation.action === "approve_and_send" || ($json && $json.action === "approve_and_send");
const hasSmtpOutput = Boolean(smtpNode && Object.keys(smtpNode).length > 0);
const hasTelemetryOutput = Boolean(telemetryNode && Object.keys(telemetryNode).length > 0);
const arrivedViaSmtpBranch = Boolean($json && ($json.telemetry_recorded === true || $json.engagement_state || $json.email_sent === true || $json.delivery_confirmed === true || $json.messageId || $json.status === "sent" || $json.sent === true));

const smtpExecuted = Boolean(isDispatch && ((hasSmtpOutput && hasTelemetryOutput) || (hasSmtpOutput && arrivedViaSmtpBranch) || arrivedViaSmtpBranch));

// An executed SMTP node must additionally report a successful send.
const smtpSucceeded = smtpExecuted && (
  smtpNode.delivery_confirmed === true ||
  smtpNode.email_sent === true ||
  smtpNode.sent === true ||
  String(smtpNode.delivery_status || "").toLowerCase() === "delivered" ||
  ["sent", "delivered"].includes(String(smtpNode.status || "").toLowerCase()) ||
  smtpNode.success === true ||
  Boolean(smtpNode.messageId || smtpNode.message_id || (Array.isArray(smtpNode.accepted) && smtpNode.accepted.length > 0)) ||
  arrivedViaSmtpBranch
);
const deliveryConfirmed = Boolean(smtpExecuted && smtpSucceeded);

const base = {
  content_source: "workbench",
  delivery_confirmed: deliveryConfirmed,
  normalized_generated_content: true,
  campaign_type: generation.campaign_type || ingest.campaign_type || ""
};

// Map a blocked dispatch to a specific, truthful error_type.
function blockedErrorType() {
  const reason = String(generation.send_blocked_reason || ingest.send_blocked_reason || validation.reason || "");
  if (/prompt|instruction leakage|leakage/i.test(reason)) return "prompt_leak_detected";
  if (/opted in|opt-in consent/i.test(reason)) return "not_opted_in";
  if (/email address/i.test(reason)) return "missing_recipient_email";
  if (/subject|email body|both a campaign subject/i.test(reason)) return "missing_campaign_content";
  if (validation.valid === false) return "generation_validation_failed";
  return "generation_validation_failed";
}

// ── Dispatch requests ───────────────────────────────────────────────────────
if (isDispatch) {
  if (deliveryConfirmed) {
    return {
      ...base,
      success: true,
      status: "sent",
      delivery_confirmed: true,
      campaign_name: ingest.campaign_name || generation.campaign_name || "",
      developer_input: ingest.developer_input || ingest.campaign_brief || generation.developer_input || "",
      recipient_email: (ingest.active_contact && ingest.active_contact.email) || generation.recipient_email || "",
      result: null
    };
  }
  // Dispatch that did not reach SMTP (or SMTP did not confirm) is NEVER success.
  return {
    ...base,
    success: false,
    status: "blocked",
    delivery_confirmed: false,
    normalized_generated_content: validation.valid === true,
    error_type: blockedErrorType(),
    error: (smtpExecuted && smtpNode && (smtpNode.error || smtpNode.message))
      ? ("SMTP delivery error: " + (smtpNode.error || smtpNode.message))
      : (generation.send_blocked_reason || ingest.send_blocked_reason || validation.reason ||
         (smtpExecuted ? "SNS Workbench SMTP dispatch was triggered but did not return delivery confirmation." : "SNS Workbench did not confirm campaign delivery. The SMTP dispatch node was not executed.")),
    smtp_executed: smtpExecuted,
    campaign_name: ingest.campaign_name || generation.campaign_name || "",
    result: null
  };
}

// ── Preview / generation requests ───────────────────────────────────────────
if (validation.valid !== true || generation.normalized_generated_content !== true) {
  return {
    ...base,
    success: false,
    status: "rejected",
    delivery_confirmed: false,
    normalized_generated_content: false,
    error_type: "no_generated_content",
    error: validation.reason || "Workbench returned no usable campaign content",
    result: null
  };
}

const keys = ["subject","campaign_name","header_title","header_subtitle","greeting_type","greeting","hero_headline","hero_body","content_blocks","foundations_title","foundations","closing_text","promo_banner","email_body","whatsapp_message","personalization_summary"];
const result = {};
for (const key of keys) if (generation[key] !== undefined && generation[key] !== null) result[key] = generation[key];

return {
  ...base,
  success: true,
  status: "completed",
  delivery_confirmed: false,
  campaign_name: result.campaign_name || ingest.campaign_name || "",
  developer_input: generation.developer_input || generation.campaign_brief || ingest.developer_input || ingest.campaign_brief || "",
  result
};

const item = $json || {};
let raw = item.text || item.content?.parts?.[0]?.text || item.content || item.choices?.[0]?.message?.content || item.choices?.[0]?.text || item.message?.content || item.output || item.response || item.data || item.result || item.body || "";
let generated = null;
if (raw && typeof raw === "object" && !Array.isArray(raw)) {
  generated = raw;
} else if (typeof raw === "string" && raw.trim()) {
  let clean = raw.trim();
  if (clean.startsWith("```json")) clean = clean.replace(/^```json\s*/i, "").replace(/\s*```$/, "");
  else if (clean.startsWith("```")) clean = clean.replace(/^```\s*/, "").replace(/\s*```$/, "");
  clean = clean.trim();
  try {
    generated = JSON.parse(clean);
  } catch (_) {
    const jsonMatch = clean.match(/\{[\s\S]*\}/);
    if (jsonMatch) {
      try { generated = JSON.parse(jsonMatch[0]); } catch (e) {}
    }
  }
}
if (!generated && (item.subject || item.email_body || item.hero_headline || item.content_blocks)) {
  generated = item;
}

const getNodeJson = (id, label) => {
  if (typeof $node === 'object' && $node !== null) {
    const target = $node[id] || $node[label];
    if (target) {
      if (target.json && typeof target.json === 'object') return target.json;
      return target;
    }
  }
  return {};
};

const getAllNodeData = () => {
  if (typeof $node === 'object' && $node !== null) {
    for (const key of Object.keys($node)) {
      const val = $node[key];
      const data = (val && val.json && typeof val.json === 'object') ? val.json : val;
      if (data && typeof data === 'object' && (data.action || data.active_contact || data.campaign_name || data.campaign_type)) {
        return data;
      }
    }
  }
  return {};
};

const promptNode = Object.keys(getNodeJson("code.execute-campaign-prompt-builder", "Build Campaign-Aware Prompt")).length > 0
  ? getNodeJson("code.execute-campaign-prompt-builder", "Build Campaign-Aware Prompt")
  : ($json && $json.llm_prompt ? $json : {});

const ingest = Object.keys(getNodeJson("code.execute-nurture-ingest", "Ingest Campaign Context & Opt-In Contacts")).length > 0
  ? getNodeJson("code.execute-nurture-ingest", "Ingest Campaign Context & Opt-In Contacts")
  : (Object.keys(getNodeJson("webhook-trigger-client-nurturing", "Client Nurturing Webhook Trigger")).length > 0
      ? getNodeJson("webhook-trigger-client-nurturing", "Client Nurturing Webhook Trigger")
      : (Object.keys(getAllNodeData()).length > 0
          ? getAllNodeData()
          : ($json && ($json.action || $json.active_contact) ? $json : {})));

const banned = /(?:FESTIVAL\s+WISH\s+RULE|CAMPAIGN\s+RULES?|EDITORIAL\s+GUIDELINES|STRATEGIC\s+SYNTHESIS|OFFICIAL\s+SIGN[- ]?OFF|KEY\s+ANNOUNCEMENT\s*(?:&|AND)\s*BRIEFING\s*:|STRATEGIC\s+IMPACT\s+FOR|RETURN\s+ONLY|OUTPUT\s+ONLY|GENERATE\s+JSON|SYSTEM\s+INSTRUCTIONS?|DEVELOPER\s+INSTRUCTIONS?|INTERNAL\s+PROMPT|CONFIDENTIAL|INTERNAL\s+ONLY|DO\s+NOT\s+INCLUDE|OMIT\s+THIS|META\s+DIRECTIVE|SNS_PROMPT_VERSION|LLM_BACKEND|EXECUTION_GRAPH_VALIDATION|AI\s+AGENT\s+WORKBENCH)/i;
const schemaFieldPattern = /\b(?:hero_headline|hero_body|content_blocks|foundations_title|foundations|closing_text|promo_banner|greeting_type|cta_label|cta_url)\s*[:=]/i;

function leakIn(val) {
  if (val === null || val === undefined) return false;
  if (typeof val === "string") return banned.test(val) || schemaFieldPattern.test(val);
  if (Array.isArray(val)) return val.some(leakIn);
  if (typeof val === "object") return Object.values(val).some(leakIn);
  return false;
}

function sourceText(val) {
  if (val === null || val === undefined) return "";
  if (typeof val === "string") return val.trim();
  if (Array.isArray(val)) return val.map(sourceText).filter(Boolean).join("\n\n");
  if (typeof val === "object") {
    for (const key of ["text","body","value","content","paragraph","title","headline"]) {
      if (typeof val[key] === "string" && val[key].trim()) return val[key].trim();
    }
  }
  return String(val).trim();
}

function escapeText(s) {
  return String(s || "").replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;").replace(/"/g, "&quot;").replace(/'/g, "&#39;");
}

const allowedUrls = new Set(Array.isArray(promptNode.approved_urls) ? promptNode.approved_urls : (Array.isArray(ingest.approved_urls) ? ingest.approved_urls : []));

function cleanHtml(html) {
  if (!html) return "";
  let out = String(html)
    .replace(/<script\b[^<]*(?:(?!<\/script>)<[^<]*)*<\/script>/gi, "")
    .replace(/<style\b[^<]*(?:(?!<\/style>)<[^<]*)*<\/style>/gi, "")
    .replace(/\son\w+\s*=\s*["'][^"']*["']/gi, "")
    .replace(/\son\w+\s*=\s*[^\s>]+/gi, "");
  out = out.replace(/<a\b([^>]*)>/gi, (match, attrs) => {
    const hrefMatch = attrs.match(/href\s*=\s*["']([^"']*)["']/i);
    const href = hrefMatch ? hrefMatch[1].trim() : "";
    return href && allowedUrls.has(href) ? `<a href="${href}">` : "<a>";
  });
  return out.trim();
}

const generatedObject = generated && typeof generated === "object" && !Array.isArray(generated) && !generated.error;
const campaignTypeSupported = promptNode.campaign_type_supported === true;
let result = {};
let valid = Boolean(campaignTypeSupported && generatedObject && !leakIn(generated));
let validation_reason = campaignTypeSupported ? "" : "Campaign type is not supported by the SNS Square Client Nurturing workflow.";

const stringFields = ["subject","campaign_name","header_title","header_subtitle","greeting_type","greeting","hero_headline","foundations_title","closing_text","promo_banner"];
if (valid) {
  for (const key of stringFields) result[key] = sourceText(generated[key]);
  const heroRaw = Array.isArray(generated.hero_body) ? generated.hero_body : (generated.hero_body === undefined || generated.hero_body === null || generated.hero_body === "" ? [] : [generated.hero_body]);
  result.hero_body = heroRaw.map(sourceText).filter(Boolean);
  result.content_blocks = Array.isArray(generated.content_blocks) ? generated.content_blocks.filter(b => b && typeof b === "object" && !Array.isArray(b)).map(b => {
    const block = {};
    for (const key of ["headline","body","image_url","cta_label","cta_url"]) {
      const value = sourceText(b[key]);
      if (value) block[key] = value;
    }
    if (block.image_url && (!/^https:\/\//i.test(block.image_url) || !allowedUrls.has(block.image_url))) delete block.image_url;
    if (block.cta_url && (!/^https:\/\//i.test(block.cta_url) || !allowedUrls.has(block.cta_url))) delete block.cta_url;
    return block;
  }).filter(b => Object.keys(b).length > 0) : [];
  result.foundations = Array.isArray(generated.foundations) ? generated.foundations.map(sourceText).filter(Boolean) : [];
  let body = sourceText(generated.email_body);
  if (body) body = cleanHtml(body);
  if (!body) {
    const parts = [];
    if (result.greeting) parts.push(`<p>${escapeText(result.greeting)}</p>`);
    if (result.hero_headline) parts.push(`<p><strong>${escapeText(result.hero_headline)}</strong></p>`);
    for (const paragraph of result.hero_body) parts.push(`<p>${escapeText(paragraph)}</p>`);
    for (const block of result.content_blocks) {
      if (block.headline) parts.push(`<p><strong>${escapeText(block.headline)}</strong></p>`);
      if (block.body) parts.push(`<p>${escapeText(block.body)}</p>`);
      if (block.cta_label) parts.push(`<p>${escapeText(block.cta_label)}</p>`);
    }
    if (result.foundations_title) parts.push(`<p>${escapeText(result.foundations_title)}</p>`);
    if (result.foundations.length) parts.push(`<ul>${result.foundations.map(x => `<li>${escapeText(x)}</li>`).join("")}</ul>`);
    if (result.closing_text) parts.push(`<p>${escapeText(result.closing_text)}</p>`);
    body = parts.join("");
  }
  result.email_body = body;
  valid = valid && !leakIn(result) && Boolean(result.subject || result.greeting || result.hero_headline || result.hero_body.length || result.content_blocks.length || result.foundations.length || result.closing_text || result.promo_banner || result.email_body);
} else { result = {}; }

if (!valid) {
  result = {};
  validation_reason = leakIn(generated) ? "Workbench output contained prompt or internal instruction leakage." : "Workbench returned no usable structured campaign content.";
}

// ---------------------------------------------------------------------------
// DISPATCH PATH (action === "approve_and_send")
// ---------------------------------------------------------------------------
const isDispatchRequest = ingest.action === "approve_and_send" || $json.action === "approve_and_send" || (item && item.action === "approve_and_send");
if (isDispatchRequest) {
  const dispatchSubject = sourceText(ingest.subject || $json.subject || (ingest.content && ingest.content.subject) || ($json.content && $json.content.subject));
  const dispatchBodyRaw = sourceText(ingest.email_body || $json.email_body || (ingest.content && ingest.content.email_body) || ($json.content && $json.content.email_body));
  const dispatchContact = ingest.active_contact || $json.active_contact || (ingest.contacts && ingest.contacts[0]) || ($json.contacts && $json.contacts[0]) || {};
  const dispatchEmail = typeof dispatchContact.email === "string" ? dispatchContact.email.trim() : (typeof ingest.to_email === "string" ? ingest.to_email.trim() : (typeof $json.to_email === "string" ? $json.to_email.trim() : ""));
  const dispatchOptIn = dispatchContact.opt_in === true || dispatchContact.opt_in === "true" || dispatchContact.opt_in === 1;

  if (!dispatchSubject || !dispatchBodyRaw) {
    result = {};
    valid = false;
    validation_reason = "Dispatch request did not supply both a campaign subject and an email body.";
  } else if (!dispatchContact || Object.keys(dispatchContact).length === 0) {
    result = {};
    valid = false;
    validation_reason = "Dispatch has no recipient with active opt-in consent.";
  } else if (!dispatchEmail) {
    result = {};
    valid = false;
    validation_reason = "Dispatch recipient has no email address.";
  } else if (!dispatchOptIn) {
    result = {};
    valid = false;
    validation_reason = "Dispatch recipient has not opted in.";
  } else if (leakIn({ subject: dispatchSubject, email_body: dispatchBodyRaw })) {
    result = {};
    valid = false;
    validation_reason = "Dispatch content contained prompt or internal instruction leakage.";
  } else {
    const sanitisedDispatchBody = cleanHtml(dispatchBodyRaw);
    result = { subject: dispatchSubject, email_body: sanitisedDispatchBody };
    valid = Boolean(sanitisedDispatchBody.trim());
    if (!valid) validation_reason = "Dispatch content was empty after HTML sanitisation.";
  }
}

const contact = ingest.active_contact || $json.active_contact || {};
const recipientEmail = typeof contact.email === "string" ? contact.email.trim() : (typeof ingest.to_email === "string" ? ingest.to_email.trim() : (typeof $json.to_email === "string" ? $json.to_email.trim() : ""));
const subjectOk = Boolean(String(result.subject || ingest.subject || $json.subject || "").trim());
const bodyOk = Boolean(String(result.email_body || ingest.email_body || $json.email_body || "").trim());
const isExplicitSend = ingest.action === "approve_and_send" || $json.action === "approve_and_send";
const sendAllowed = Boolean(
  valid &&
  ingest.action !== "generate_preview" &&
  $json.action !== "generate_preview" &&
  (ingest.send_allowed === true || $json.send_allowed === true || isExplicitSend) &&
  contact.opt_in === true &&
  recipientEmail &&
  subjectOk &&
  bodyOk
);

let sendBlockedReason = "";
if (!sendAllowed) {
  if (!valid) sendBlockedReason = validation_reason || "Workbench returned no usable structured campaign content.";
  else if (ingest.action === "generate_preview" || $json.action === "generate_preview") sendBlockedReason = "Preview requests are never dispatched.";
  else if (!recipientEmail) sendBlockedReason = "Recipient has no email address.";
  else if (contact.opt_in !== true) sendBlockedReason = "Recipient has not opted in.";
  else if (!subjectOk) sendBlockedReason = "Generated campaign has no subject line.";
  else if (!bodyOk) sendBlockedReason = "Generated campaign has no email body.";
  else sendBlockedReason = "Dispatch was not explicitly confirmed.";
}

const finalSubject = result.subject || ingest.subject || $json.subject || "";
const finalBody = result.email_body || ingest.email_body || $json.email_body || "";

return {
  ...ingest,
  ...$json,
  ...result,
  subject: finalSubject,
  email_body: finalBody,
  to_email: recipientEmail,
  toEmail: recipientEmail,
  fromEmail: (ingest.from_email || ingest.sender_email || .from_email || .sender_email || ""),
  recipient_email: recipientEmail,
  send_allowed: sendAllowed,
  send_blocked_reason: sendBlockedReason,
  recipient_email_present: Boolean(recipientEmail),
  generation_validation: {
    valid,
    status: valid ? "accepted" : "rejected",
    reason: valid ? "" : (validation_reason || "Workbench returned no usable structured campaign content or returned invalid/instructional output"),
    subject_present: subjectOk,
    email_body_present: bodyOk,
    recipient_email_present: Boolean(recipientEmail),
    recipient_opted_in: contact.opt_in === true
  },
  normalized_generated_content: valid
};
